values ('e2acf72f-9e57-4f7a-a0ee-89aed453dd32', 'eggs, leftover rice, kimchi, scallions', 'any', 'Kimchi Fried Rice with Egg', 'A quick and flavorful fried rice, perfectly balancing the tang of kimchi with a rich fried egg, ideal for a satisfying meal.', '[{"item": "leftover rice", "amount": "2 cups"}, {"item": "kimchi", "amount": "1/2 cup, chopped"}, {"item": "eggs", "amount": "1-2"}, {"item": "scallions", "amount": "1, sliced"}, {"item": "soy sauce", "amount": "1 tbsp"}, {"item": "sesame oil", "amount": "1 tsp"}]'::jsonb, '["Heat a non-stick pan or wok over medium-high heat with a drizzle of oil.", "Add the chopped kimchi and cook for 2-3 minutes until slightly softened and fragrant.", "Add the leftover rice, breaking up any clumps, and stir-fry for 5-7 minutes until heated through and slightly crispy.", "Stir in the soy sauce and sesame oil, mixing well to combine.", "Make a space in the pan, crack an egg into it, and cook to your desired doneness (fried, scrambled, or sunny-side up).", "Serve the kimchi fried rice immediately, topped with the cooked egg and sliced scallions."]'::jsonb, 20, 1, 'seed/r00.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: eggs, leftover rice, kimchi, scallions
Dietary preference: No restrictions', null, '2026-10-19T11:40:50-04:00');
