values ('dc713d96-0c0f-4195-817a-f08a1745d6d8', 'instant ramen, eggs, cheese slice, spam', 'dorm-friendly', 'Cheesy Spam & Egg Ramen Scramble', 'A quick and satisfying upgrade to instant ramen, featuring savory spam, gooey cheese, and a fluffy egg scramble, all made in one pan or microwave.', '[{"item": "Instant ramen", "amount": "1 pack"}, {"item": "Egg", "amount": "1"}, {"item": "Cheese slice", "amount": "1"}, {"item": "Spam", "amount": "2 oz"}, {"item": "Water", "amount": "2 cups"}, {"item": "Soy sauce", "amount": "1 tsp"}]'::jsonb, '["Dice spam into small cubes.", "In a microwave-safe bowl or small pan, cook spam until crispy.", "Remove spam, leaving any rendered fat. If using a pan, scramble egg in the same pan. If microwaving, whisk egg and microwave until cooked through, then break apart.", "Add water and ramen noodles to the bowl/pan. Microwave or boil until noodles are tender, about 2-3 minutes.", "Stir in ramen seasoning packet and soy sauce.", "Top with cooked spam, scrambled egg, and cheese slice. Microwave or cover until cheese is melted.", "Stir everything together until well combined and serve immediately."]'::jsonb, 15, 1, 'seed/r01.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: instant ramen, eggs, cheese slice, spam
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-11T11:41:58-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'chicken thighs, garlic, soy sauce, honey, broccoli', 'high-protein', 'Sticky Honey Garlic Chicken & Broccoli', 'Tender chicken thighs and crisp broccoli florets coated in a savory-sweet honey garlic glaze, making for a satisfying high-protein meal.', '[{"item": "Chicken thighs", "amount": "1 lb"}, {"item": "Garlic", "amount": "4 cloves"}, {"item": "Soy sauce", "amount": "1/4 cup"}, {"item": "Honey", "amount": "1/4 cup"}, {"item": "Broccoli", "amount": "1 head"}, {"item": "Cornstarch", "amount": "1 tsp"}]'::jsonb, '["Pat chicken thighs dry and season with salt and pepper.", "Chop broccoli into florets; mince garlic.", "Whisk together soy sauce, honey, minced garlic, and cornstarch in a small bowl.", "Heat a large pan with a little oil over medium-high heat. Sear chicken thighs skin-side down for 5-7 minutes until golden brown, then flip and cook for another 5 minutes.", "Add broccoli florets to the pan with the chicken and cook for 3-5 minutes, stirring occasionally.", "Pour the honey garlic sauce over the chicken and broccoli. Simmer for 5-7 minutes, stirring occasionally, until the sauce thickens and coats everything.", "Ensure chicken is cooked through (internal temperature 165\u00b0F/74\u00b0C).", "Serve immediately."]'::jsonb, 35, 2, 'seed/r02.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: chicken thighs, garlic, soy sauce, honey, broccoli
Dietary preference: High protein', null, '2026-10-02T18:41:44-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ddd1dfb2-3b98-4ef8-9af6-1a26146d3f31', 'canned chickpeas, spinach, coconut milk, curry powder', 'vegan', 'Quick Coconut Chickpea & Spinach Curry', 'A creamy, aromatic, and satisfying vegan curry that comes together in a flash.', '[{"item": "Canned chickpeas, drained and rinsed", "amount": "1 can (15 oz)"}, {"item": "Fresh spinach", "amount": "5 oz"}, {"item": "Full-fat coconut milk", "amount": "1 can (13.5 oz)"}, {"item": "Curry powder", "amount": "1 tbsp"}, {"item": "Onion, chopped", "amount": "1/2"}, {"item": "Garlic, minced", "amount": "2 cloves"}]'::jsonb, '["Heat a tablespoon of oil in a medium pot or skillet over medium heat.", "Add the chopped onion and cook until softened, about 3-4 minutes. Stir in the minced garlic and curry powder, cooking for another minute until fragrant.", "Pour in the coconut milk and bring to a gentle simmer. Add the drained chickpeas.", "Continue to simmer for 5-7 minutes, allowing the flavors to meld and the sauce to thicken slightly.", "Stir in the fresh spinach a handful at a time, allowing it to wilt down before adding more.", "Cook for another 2-3 minutes, until all the spinach is wilted and heated through. Season with salt and pepper to taste.", "Serve hot, perhaps with rice or naan if available."]'::jsonb, 25, 2, 'seed/r03.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: canned chickpeas, spinach, coconut milk, curry powder
Dietary preference: Vegan', null, '2026-10-01T19:15:38-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('43b7a3a6-9a8d-4a03-980d-7b71d8f56413', 'pasta, cherry tomatoes, garlic, parmesan, basil', 'vegetarian', 'One-Pan Cherry Tomato Basil Pasta', 'A vibrant and fresh pasta dish bursting with the sweet and savory flavors of roasted cherry tomatoes, fragrant garlic, and fresh basil, all tied together with salty Parmesan.', '[{"item": "pasta", "amount": "200g"}, {"item": "cherry tomatoes", "amount": "2 cups"}, {"item": "garlic", "amount": "3 cloves"}, {"item": "parmesan cheese", "amount": "1/2 cup grated"}, {"item": "fresh basil", "amount": "1/4 cup chopped"}, {"item": "olive oil", "amount": "2 tbsp"}, {"item": "red pepper flakes", "amount": "1/4 tsp (optional)"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C).", "In a baking dish, toss cherry tomatoes, minced garlic, olive oil, salt, pepper, and red pepper flakes (if using).", "Roast for 20-25 minutes, or until tomatoes are bursting and slightly caramelized.", "While tomatoes roast, cook pasta according to package directions until al dente; reserve 1/2 cup pasta water.", "Add cooked pasta to the baking dish with the roasted tomatoes, along with the fresh basil and half of the Parmesan.", "Toss everything together, adding a splash of reserved pasta water as needed to create a light sauce.", "Serve immediately, garnished with the remaining Parmesan cheese."]'::jsonb, 35, 2, 'seed/r04.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: pasta, cherry tomatoes, garlic, parmesan, basil
Dietary preference: Vegetarian', null, '2026-10-19T17:43:33-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('3eabedcb-baa8-4dd4-88bd-64072bcfbe01', 'tortillas, black beans, cheddar, salsa, avocado', 'vegetarian', 'Cheesy Black Bean & Avocado Quesadillas', 'Quick and satisfying quesadillas bursting with creamy avocado, savory black beans, and melted cheddar, all griddled to golden perfection.', '[{"item": "Flour tortillas", "amount": "4 large"}, {"item": "Canned black beans, rinsed and drained", "amount": "1 (15-ounce) can"}, {"item": "Cheddar cheese, shredded", "amount": "1 cup"}, {"item": "Salsa", "amount": "1/2 cup"}, {"item": "Avocado, sliced or mashed", "amount": "1 large"}, {"item": "Vegetable oil", "amount": "1 tbsp"}]'::jsonb, '["In a small bowl, lightly mash the rinsed black beans with a fork, leaving some whole.", "Heat 1/2 tablespoon of oil in a large non-stick skillet over medium heat.", "Place one tortilla in the skillet, sprinkle half of the cheddar cheese over one half of the tortilla.", "Spoon half of the mashed black beans, sliced avocado, and a dollop of salsa over the cheese.", "Fold the other half of the tortilla over the filling to create a half-moon shape.", "Cook for 3-4 minutes per side, until golden brown and the cheese is melted.", "Remove from skillet, slice into wedges, and repeat with the remaining ingredients for the second quesadilla.", "Serve immediately with extra salsa for dipping."]'::jsonb, 20, 2, 'seed/r05.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: tortillas, black beans, cheddar, salsa, avocado
Dietary preference: Vegetarian', null, '2026-10-17T19:24:30-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('aefcfad8-efc8-4849-b3aa-7efe4458a885', 'oats, banana, peanut butter, milk', 'dorm-friendly', 'Peanut Butter Banana Overnight Oats', 'A creamy, satisfying, and super easy breakfast that''s ready to grab and go from your fridge.', '[{"item": "Rolled oats", "amount": "1/2 cup"}, {"item": "Milk", "amount": "1 cup"}, {"item": "Peanut butter", "amount": "2 tablespoons"}, {"item": "Banana", "amount": "1/2"}, {"item": "Chia seeds", "amount": "1 tablespoon"}, {"item": "Maple syrup", "amount": "1 teaspoon"}]'::jsonb, '["In a jar or container, combine oats, milk, peanut butter, chia seeds, and maple syrup.", "Stir well until all ingredients are thoroughly mixed and peanut butter is dissolved.", "Slice half of the banana and add to the mixture, stirring gently.", "Cover the container and refrigerate for at least 4 hours, or preferably overnight.", "In the morning, give it a quick stir and enjoy cold. Add more sliced banana if desired."]'::jsonb, 5, 1, 'seed/r06.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: oats, banana, peanut butter, milk
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-05T21:33:00-04:00');
