values ('b74d0fb1-32e7-4629-8fad-c1a606cb0fb3', 'ground beef, potatoes, onion, carrots', 'any', 'Hearty Beef and Potato Hash', 'A comforting and satisfying one-pan meal, perfect for a quick and delicious dinner.', '[{"item": "Ground Beef", "amount": "1 lb"}, {"item": "Potatoes", "amount": "2 medium"}, {"item": "Onion", "amount": "1 small"}, {"item": "Carrots", "amount": "2 medium"}, {"item": "Garlic powder", "amount": "1 tsp"}, {"item": "Paprika", "amount": "1 tsp"}]'::jsonb, '["Dice potatoes, onion, and carrots into small, uniform pieces.", "Heat a large skillet over medium-high heat and brown the ground beef, breaking it apart, then drain any excess fat.", "Add diced potatoes, onion, and carrots to the skillet with the beef.", "Season with salt, pepper, garlic powder, and paprika, stirring to combine.", "Reduce heat to medium, cover, and cook for 15-20 minutes, stirring occasionally, until vegetables are tender.", "Remove lid and continue to cook for another 5-7 minutes, stirring, until potatoes are slightly crispy.", "Serve hot and enjoy your hearty meal."]'::jsonb, 45, 2, 'seed/r07.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: ground beef, potatoes, onion, carrots
Dietary preference: No restrictions', null, '2026-10-10T18:42:39-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ec1b8ca1-f91e-4d4c-9ff4-9b7889463e85', 'tofu, bok choy, ginger, soy sauce, rice', 'vegan', 'Ginger-Soy Tofu & Bok Choy Stir-fry', 'A quick and flavorful vegan stir-fry featuring crispy tofu and tender bok choy, all coated in a savory ginger-soy sauce.', '[{"item": "firm tofu", "amount": "1 block (14 oz)"}, {"item": "bok choy", "amount": "4 heads"}, {"item": "fresh ginger", "amount": "2-inch piece"}, {"item": "soy sauce", "amount": "1/4 cup"}, {"item": "uncooked rice", "amount": "1 cup"}, {"item": "cornstarch", "amount": "1 tbsp"}, {"item": "sesame oil", "amount": "1 tsp"}]'::jsonb, '["Press tofu to remove excess water, then cut into 1-inch cubes and toss with 1/2 tbsp cornstarch.", "Cook rice according to package directions.", "Heat 1 tbsp oil in a large skillet or wok over medium-high heat. Add tofu and cook until golden and crispy on all sides, about 8-10 minutes. Remove tofu and set aside.", "While tofu cooks, mince ginger and chop bok choy, separating white stems from green leaves.", "Add a little more oil to the skillet if needed. Stir-fry bok choy stems for 2 minutes, then add leaves and ginger, cooking for another 2-3 minutes until bright green and slightly tender.", "In a small bowl, whisk together soy sauce, sesame oil, and remaining 1/2 tbsp cornstarch with 2 tbsp water.", "Return tofu to the skillet. Pour in the sauce and cook, stirring constantly, until the sauce thickens and coats the tofu and bok choy.", "Serve immediately over hot rice."]'::jsonb, 30, 2, 'seed/r08.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: tofu, bok choy, ginger, soy sauce, rice
Dietary preference: Vegan', null, '2026-10-12T13:43:31-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('e2acf72f-9e57-4f7a-a0ee-89aed453dd32', 'salmon, lemon, asparagus, butter', 'high-protein', 'Lemon Butter Salmon with Roasted Asparagus', 'Flaky salmon and tender-crisp asparagus roasted together with a bright lemon-butter sauce for a healthy and satisfying meal.', '[{"item": "salmon fillets", "amount": "2 (6 oz each)"}, {"item": "lemon", "amount": "1"}, {"item": "asparagus spears", "amount": "1 bunch (about 1 lb)"}, {"item": "unsalted butter", "amount": "2 tablespoons"}, {"item": "garlic powder", "amount": "1/2 teaspoon"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C). Line a baking sheet with parchment paper.", "Melt butter in a small microwave-safe bowl. Stir in garlic powder, and the juice of half the lemon.", "Trim the woody ends off the asparagus. Toss asparagus with 1 tablespoon of the lemon-butter mixture, salt, and pepper on one side of the baking sheet.", "Pat salmon fillets dry. Place salmon on the other side of the baking sheet. Season with salt and pepper.", "Brush the remaining lemon-butter mixture over the salmon fillets.", "Thinly slice the remaining half lemon and place a slice or two on top of each salmon fillet.", "Roast for 12-18 minutes, or until salmon is cooked through and flakes easily with a fork, and asparagus is tender-crisp.", "Serve immediately with extra lemon wedges if desired."]'::jsonb, 30, 2, 'seed/r09.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: salmon, lemon, asparagus, butter
Dietary preference: High protein', null, '2026-10-07T16:28:15-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('bd9c66b3-ad3c-4d6d-9a3d-1fa7bc8960a9', 'bagel, cream cheese, smoked salmon, cucumber', 'any', 'Smoked Salmon & Cream Cheese Bagel', 'A classic and satisfying bagel sandwich, perfect for a quick and elegant meal.', '[{"item": "Bagel", "amount": "1"}, {"item": "Cream Cheese", "amount": "2 tbsp"}, {"item": "Smoked Salmon", "amount": "2 oz"}, {"item": "Cucumber", "amount": "1/4"}, {"item": "Fresh Dill (optional)", "amount": "1 tsp"}]'::jsonb, '["Slice the bagel in half and toast to your desired crispness.", "While the bagel toasts, thinly slice the cucumber.", "Once toasted, spread a generous layer of cream cheese on both halves of the bagel.", "Layer the smoked salmon over the cream cheese.", "Arrange the cucumber slices on top of the salmon.", "If using, sprinkle fresh dill over the cucumber and salmon.", "Assemble the bagel and serve immediately."]'::jsonb, 10, 1, 'seed/r10.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: bagel, cream cheese, smoked salmon, cucumber
