insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ec1b8ca1-f91e-4d4c-9ff4-9b7889463e85', 'frozen dumplings, cabbage, chili oil, vinegar', 'dorm-friendly', 'Chili Oil Cabbage and Dumpling Stir-Fry', 'A quick and satisfying microwave-friendly meal featuring savory dumplings and tender cabbage tossed in a spicy, tangy chili oil sauce.', '[{"item": "frozen dumplings", "amount": "10-12"}, {"item": "cabbage", "amount": "2 cups, shredded"}, {"item": "chili oil", "amount": "1-2 tbsp"}, {"item": "vinegar", "amount": "1 tbsp"}, {"item": "soy sauce", "amount": "1 tbsp"}]'::jsonb, '["Place frozen dumplings in a microwave-safe bowl with 2 tablespoons of water, cover, and microwave for 3-4 minutes, or until cooked through.", "In a separate microwave-safe bowl, combine shredded cabbage with 1 tablespoon of water, cover, and microwave for 2-3 minutes, until tender-crisp.", "Drain any excess water from the cooked dumplings and cabbage.", "In a large bowl or directly in your serving bowl, combine the cooked dumplings and cabbage.", "Add chili oil, vinegar, and soy sauce to the bowl.", "Toss gently until all ingredients are well coated.", "Serve immediately and enjoy your dorm-friendly stir-fry!"]'::jsonb, 20, 1, 'seed/r11.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: frozen dumplings, cabbage, chili oil, vinegar
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-19T16:19:45-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'sweet potato, black beans, lime, cilantro', 'vegan', 'Sweet Potato & Black Bean Tacos', 'Hearty roasted sweet potato and seasoned black beans nestled in warm tortillas, brightened by a zesty lime-cilantro slaw.', '[{"item": "Sweet Potato", "amount": "1 large"}, {"item": "Black Beans", "amount": "1 can (15 oz)"}, {"item": "Lime", "amount": "1"}, {"item": "Cilantro", "amount": "1/2 bunch"}, {"item": "Tortillas", "amount": "6-8 small"}, {"item": "Chili Powder", "amount": "1 tsp"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C). Dice sweet potato into 1/2-inch cubes, toss with a drizzle of oil, salt, and pepper, then spread on a baking sheet.", "Roast sweet potato for 20-25 minutes, flipping halfway, until tender and slightly caramelized.", "While sweet potatoes roast, drain and rinse black beans. Heat a small amount of oil in a pan, add beans, chili powder, and a splash of water; simmer for 5 minutes.", "Chop cilantro and halve the lime. In a small bowl, combine chopped cilantro with the juice of half a lime and a pinch of salt for a quick slaw.", "Warm tortillas according to package directions. You can microwave them or heat them in a dry pan.", "Assemble tacos: Spoon roasted sweet potatoes and seasoned black beans into warm tortillas, top with the lime-cilantro slaw, and a squeeze of the remaining lime."]'::jsonb, 40, 2, 'seed/r12.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: sweet potato, black beans, lime, cilantro
Dietary preference: Vegan', null, '2026-10-18T19:28:31-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('dc713d96-0c0f-4195-817a-f08a1745d6d8', 'greek yogurt, chicken breast, cucumber, pita', 'high-protein', 'High-Protein Chicken Gyro Bowl', 'A flavorful and satisfying bowl packed with protein, featuring tender chicken, cool cucumber, and creamy Greek yogurt over warm pita.', '[{"item": "chicken breast", "amount": "2 (about 1 lb)"}, {"item": "greek yogurt", "amount": "1 cup"}, {"item": "cucumber", "amount": "1"}, {"item": "pita bread", "amount": "2"}, {"item": "lemon juice", "amount": "1 tbsp"}, {"item": "garlic powder", "amount": "1 tsp"}]'::jsonb, '["Slice chicken breast into thin strips and season with salt, pepper, and 1/2 tsp garlic powder.", "Heat a pan with a little oil over medium-high heat and cook chicken until browned and cooked through, about 5-7 minutes.", "While chicken cooks, finely dice the cucumber.", "In a small bowl, mix Greek yogurt with lemon juice, remaining 1/2 tsp garlic powder, and a pinch of salt and pepper to make the tzatziki.", "Warm the pita bread in the microwave or a dry pan for 30 seconds.", "Assemble bowls by placing warm pita on the bottom, topping with cooked chicken, diced cucumber, and a generous dollop of tzatziki."]'::jsonb, 30, 2, 'seed/r13.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: greek yogurt, chicken breast, cucumber, pita
Dietary preference: High protein', null, '2026-10-20T15:00:00-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('47378190-96da-4dac-b2ff-5d2a386ecbe0', 'mushrooms, arborio rice, onion, parmesan, white wine', 'vegetarian', 'Classic Mushroom Risotto', 'Creamy, savory, and utterly comforting, this mushroom risotto is a rich and satisfying dish perfect for a cozy night in.', '[{"item": "Arborio rice", "amount": "1 cup"}, {"item": "Mushrooms", "amount": "8 oz"}, {"item": "Onion", "amount": "1/2 medium"}, {"item": "Parmesan cheese", "amount": "1/2 cup grated"}, {"item": "Dry white wine", "amount": "1/2 cup"}, {"item": "Vegetable broth", "amount": "4 cups"}, {"item": "Olive oil", "amount": "2 tbsp"}]'::jsonb, '["Heat vegetable broth in a separate pot and keep it at a simmer.", "Chop the onion finely and slice the mushrooms; saut\u00e9 them in olive oil in a large pan until softened.", "Add the arborio rice to the pan and toast for 1-2 minutes until edges are translucent.", "Pour in the white wine and stir until it''s fully absorbed by the rice.", "Begin adding the warm broth, one ladleful at a time, stirring constantly and waiting for each addition to be absorbed before adding the next.", "Continue this process for about 20-25 minutes, or until the rice is creamy and al dente.", "Remove from heat, stir in the grated Parmesan cheese, and season with salt and pepper to taste.", "Serve immediately, garnished with a little extra Parmesan if desired."]'::jsonb, 45, 2, 'seed/r14.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: mushrooms, arborio rice, onion, parmesan, white wine
Dietary preference: Vegetarian', null, '2026-10-13T14:33:16-04:00');
