values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'eggs, bread, milk, cinnamon, maple syrup', 'vegetarian', 'Classic Cinnamon French Toast', 'A comforting and sweet breakfast, perfect for a cozy morning, made with simple ingredients.', '[{"item": "large eggs", "amount": "2"}, {"item": "milk", "amount": "1/2 cup"}, {"item": "ground cinnamon", "amount": "1 tsp"}, {"item": "bread slices (preferably challah or brioche, but any will do)", "amount": "4"}, {"item": "maple syrup", "amount": "for serving"}, {"item": "butter or cooking oil", "amount": "1 tbsp"}]'::jsonb, '["In a shallow dish, whisk together the eggs, milk, and cinnamon until well combined.", "Heat a non-stick pan or griddle over medium heat and add butter or cooking oil.", "Dip each slice of bread into the egg mixture, ensuring both sides are coated but not soggy.", "Place the coated bread slices onto the hot pan and cook for 2-3 minutes per side, or until golden brown and cooked through.", "Remove the French toast from the pan and repeat with any remaining slices.", "Serve immediately, drizzled generously with maple syrup."]'::jsonb, 25, 2, 'seed/r15.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: eggs, bread, milk, cinnamon, maple syrup
Dietary preference: Vegetarian', null, '2026-10-14T17:38:30-04:00');
