values ('ddd1dfb2-3b98-4ef8-9af6-1a26146d3f31', 'udon, beef, onion, egg', 'any', 'Beef Udon Stir-fry', 'A quick and hearty stir-fry featuring tender beef, sweet onions, and chewy udon noodles, all brought together with a savory sauce and topped with a fried egg.', '[{"item": "Udon noodles", "amount": "2 servings (200-250g)"}, {"item": "Beef (sirloin or flank)", "amount": "200g"}, {"item": "Onion", "amount": "1 medium"}, {"item": "Egg", "amount": "2"}, {"item": "Soy sauce", "amount": "3 tbsp"}, {"item": "Sugar", "amount": "1 tsp"}]'::jsonb, '["Cook udon noodles according to package directions, then drain and set aside.", "Slice beef thinly against the grain and chop onion into thin wedges.", "Heat a large pan or wok with a tablespoon of oil over medium-high heat. Sear beef until browned, then remove from pan.", "Add a little more oil to the pan, then stir-fry onions until softened, about 3-4 minutes.", "Return beef to the pan, add udon noodles, soy sauce, and sugar. Toss well to combine and heat through.", "In a separate small pan, fry eggs to your desired doneness (sunny-side up or over easy).", "Divide udon stir-fry between two bowls and top each with a fried egg."]'::jsonb, 25, 2, 'seed/r16.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: udon, beef, onion, egg
Dietary preference: No restrictions', null, '2026-10-08T17:40:51-04:00');
