values ('ec1b8ca1-f91e-4d4c-9ff4-9b7889463e85', 'canned tuna, mayo, celery, bread', 'dorm-friendly', 'Quick Tuna Melts', 'Crispy, cheesy tuna melts made dorm-friendly, perfect for a satisfying lunch or dinner.', '[{"item": "canned tuna, drained", "amount": "1 can"}, {"item": "mayonnaise", "amount": "2 tbsp"}, {"item": "celery, finely diced", "amount": "1 stalk"}, {"item": "bread", "amount": "2 slices"}, {"item": "shredded cheddar cheese", "amount": "1/4 cup"}, {"item": "butter or margarine", "amount": "1 tbsp"}]'::jsonb, '["In a bowl, combine drained tuna, mayonnaise, and diced celery. Mix well.", "Butter one side of each slice of bread.", "Place one slice of bread, butter-side down, in a non-stick pan over medium heat.", "Spread the tuna mixture evenly over the bread, then top with shredded cheese.", "Place the second slice of bread, butter-side up, on top.", "Cook for 3-5 minutes per side, or until the bread is golden brown and the cheese is melted and bubbly.", "Carefully remove from pan, slice in half, and serve immediately."]'::jsonb, 15, 1, 'seed/r17.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: canned tuna, mayo, celery, bread
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-18T22:39:24-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('6c307511-b2b9-437a-a8df-6ec4ce4a2bbd', 'lentils, carrots, celery, tomato paste, cumin', 'vegan', 'Hearty Lentil & Vegetable Stew', 'A warm and satisfying vegan stew packed with earthy lentils and tender vegetables, perfect for a cozy night in.', '[{"item": "Lentils, dry", "amount": "1 cup"}, {"item": "Carrots", "amount": "2 medium"}, {"item": "Celery stalks", "amount": "2"}, {"item": "Tomato paste", "amount": "2 tbsp"}, {"item": "Cumin", "amount": "1 tsp"}, {"item": "Vegetable broth", "amount": "4 cups"}, {"item": "Garlic cloves", "amount": "2"}]'::jsonb, '["Rinse lentils. Dice carrots and celery into small pieces. Mince garlic.", "Heat a pot over medium heat with a splash of oil. Add carrots, celery, and garlic; saut\u00e9 for 5-7 minutes until slightly softened.", "Stir in tomato paste and cumin, cooking for 1 minute until fragrant.", "Add rinsed lentils and vegetable broth to the pot. Bring to a boil, then reduce heat to low.", "Cover and simmer for 30-35 minutes, or until lentils are tender, stirring occasionally.", "Season with salt and pepper to taste. Serve hot."]'::jsonb, 45, 2, 'seed/r18.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: lentils, carrots, celery, tomato paste, cumin
Dietary preference: Vegan', null, '2026-10-10T23:46:50-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('24933b83-7577-40a9-a491-f0b2ea1fca65', 'shrimp, garlic, butter, lemon, spaghetti', 'any', 'Garlic Butter Shrimp Scampi with Spaghetti', 'Quick and elegant, this dish features succulent shrimp bathed in a rich garlic-lemon butter sauce, served over a bed of al dente spaghetti.', '[{"item": "spaghetti", "amount": "6 oz"}, {"item": "shrimp, peeled and deveined", "amount": "12 oz"}, {"item": "garlic, minced", "amount": "4 cloves"}, {"item": "unsalted butter", "amount": "1/4 cup"}, {"item": "lemon, juiced and zested", "amount": "1"}, {"item": "fresh parsley, chopped", "amount": "2 tbsp"}, {"item": "red pepper flakes", "amount": "1/2 tsp"}]'::jsonb, '["Cook spaghetti according to package directions until al dente; reserve 1/2 cup pasta water, then drain.", "While pasta cooks, melt butter in a large skillet over medium heat.", "Add minced garlic and red pepper flakes to the skillet; cook for 1 minute until fragrant.", "Add shrimp to the skillet and cook for 2-3 minutes per side, until pink and opaque.", "Stir in lemon juice and zest; add the cooked spaghetti and a splash of reserved pasta water.", "Toss everything together until well combined and the sauce coats the spaghetti.", "Garnish with fresh parsley before serving."]'::jsonb, 25, 2, 'seed/r19.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: shrimp, garlic, butter, lemon, spaghetti
Dietary preference: No restrictions', null, '2026-10-11T18:03:11-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('366eb16f-508e-4ad7-b7c9-3acfe059a0ee', 'cauliflower, chickpeas, tahini, lemon', 'vegan', 'Roasted Lemon-Tahini Cauliflower & Chickpeas', 'Crispy roasted cauliflower and chickpeas coated in a bright, creamy lemon-tahini dressing make for a satisfying and flavorful vegan meal.', '[{"item": "Chickpeas", "amount": "1 can (15 oz), drained and rinsed"}, {"item": "Tahini", "amount": "1/4 cup"}, {"item": "Lemon", "amount": "1, juiced and zested"}, {"item": "Garlic powder", "amount": "1/2 tsp"}, {"item": "Cumin", "amount": "1/2 tsp"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C).", "Cut cauliflower into bite-sized florets. In a large bowl, toss cauliflower and chickpeas with 1 tbsp oil, salt, pepper, garlic powder, and cumin.", "Spread vegetables in a single layer on a baking sheet and roast for 20-25 minutes, or until tender and slightly browned.", "While vegetables roast, whisk together tahini, lemon juice, lemon zest, 2-3 tbsp water, and a pinch of salt until smooth and creamy. Add more water if needed to reach desired consistency.", "Remove roasted cauliflower and chickpeas from the oven.", "Pour the tahini dressing over the hot vegetables and toss to coat evenly.", "Serve immediately, optionally garnished with fresh parsley if available."]'::jsonb, 35, 2, 'seed/r20.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: cauliflower, chickpeas, tahini, lemon
Dietary preference: Vegan', null, '2026-10-19T19:23:31-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('bd9c66b3-ad3c-4d6d-9a3d-1fa7bc8960a9', 'pork belly, kimchi, tofu, gochujang', 'any', 'Spicy Kimchi Pork Belly Stew (Kimchi Jjigae)', 'A fiery, comforting Korean stew packed with the rich flavors of pork belly, tangy kimchi, and silky tofu.', '[{"item": "Pork belly", "amount": "200g"}, {"item": "Aged Kimchi", "amount": "1.5 cups"}, {"item": "Firm or soft tofu", "amount": "1 block (300g)"}, {"item": "Gochujang (Korean chili paste)", "amount": "1 tbsp"}, {"item": "Garlic, minced", "amount": "2 cloves"}, {"item": "Green onion, sliced", "amount": "1 stalk"}, {"item": "Water or anchovy broth", "amount": "3 cups"}]'::jsonb, '["Slice pork belly into bite-sized pieces and tofu into 1-inch cubes. Roughly chop kimchi.", "In a pot, saut\u00e9 pork belly over medium heat until lightly browned and some fat has rendered.", "Add kimchi and minced garlic to the pot, stirring well and cooking for 5-7 minutes until kimchi softens.", "Stir in gochujang, then pour in water or broth. Bring to a boil.", "Reduce heat to medium-low, add tofu, and simmer for 15-20 minutes, allowing flavors to meld.", "Taste and adjust seasoning if needed. Garnish with sliced green onions before serving.", "Serve hot with a bowl of rice."]'::jsonb, 40, 2, 'seed/r21.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: pork belly, kimchi, tofu, gochujang
Dietary preference: No restrictions', null, '2026-10-18T22:39:00-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('366eb16f-508e-4ad7-b7c9-3acfe059a0ee', 'microwave rice, eggs, frozen peas, soy sauce', 'dorm-friendly', 'Microwave Fried Rice', 'A quick and satisfying single-pan meal that transforms simple ingredients into a flavorful fried rice experience.', '[{"item": "Microwave rice", "amount": "1 packet"}, {"item": "Large egg", "amount": "1"}, {"item": "Frozen peas", "amount": "1/4 cup"}, {"item": "Soy sauce", "amount": "1-2 tbsp"}, {"item": "Sesame oil", "amount": "1 tsp"}]'::jsonb, '["Cook microwave rice according to package directions; set aside.", "Heat a non-stick pan over medium-high heat with a little oil.", "Crack the egg into the pan and scramble until just cooked, then remove.", "Add frozen peas to the pan and stir-fry for 1-2 minutes until warmed through.", "Add the cooked rice and scrambled egg back to the pan, breaking up any clumps.", "Pour in soy sauce and sesame oil, tossing everything together until well combined and heated through.", "Taste and adjust soy sauce if needed before serving immediately."]'::jsonb, 15, 1, 'seed/r22.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: microwave rice, eggs, frozen peas, soy sauce
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-05T17:30:14-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ec1b8ca1-f91e-4d4c-9ff4-9b7889463e85', 'chicken breast, quinoa, bell pepper, feta', 'high-protein', 'Mediterranean Chicken & Quinoa Bowl', 'A vibrant and protein-packed bowl featuring tender chicken, fluffy quinoa, crisp bell peppers, and tangy feta.', '[{"item": "Chicken breast", "amount": "2 (about 6 oz each)"}, {"item": "Quinoa", "amount": "1/2 cup"}, {"item": "Bell pepper", "amount": "1 large"}, {"item": "Feta cheese, crumbled", "amount": "1/4 cup"}, {"item": "Olive oil", "amount": "1 tbsp"}, {"item": "Garlic powder", "amount": "1/2 tsp"}]'::jsonb, '["Rinse quinoa well, then combine with 1 cup water and a pinch of salt in a small pot. Bring to a boil, then reduce heat, cover, and simmer for 15 minutes, or until water is absorbed.", "While quinoa cooks, pat chicken breasts dry and season generously with salt, pepper, and garlic powder.", "Slice the bell pepper into thin strips.", "Heat olive oil in a skillet over medium-high heat. Add chicken and cook for 6-8 minutes per side, or until cooked through. Remove chicken and let rest, then slice.", "In the same skillet, add bell pepper strips and saut\u00e9 for 5-7 minutes until slightly tender-crisp.", "Fluff quinoa with a fork. Divide quinoa between two bowls, then top with sliced chicken, saut\u00e9ed bell peppers, and crumbled feta."]'::jsonb, 40, 2, 'seed/r23.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: chicken breast, quinoa, bell pepper, feta
Dietary preference: High protein', null, '2026-10-18T18:38:20-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('3eabedcb-baa8-4dd4-88bd-64072bcfbe01', 'potatoes, eggs, onion, olive oil', 'vegetarian', 'Spanish Tortilla (Patata Omelette)', 'A classic, hearty Spanish tortilla made with thinly sliced potatoes, sweet onions, and eggs, perfect for any meal.', '[{"item": "Potatoes", "amount": "2 large"}, {"item": "Eggs", "amount": "6 large"}, {"item": "Onion", "amount": "1 medium"}, {"item": "Olive oil", "amount": "1/2 cup"}, {"item": "Salt", "amount": "to taste"}, {"item": "Black pepper", "amount": "to taste"}]'::jsonb, '["Peel and thinly slice potatoes into rounds or half-moons; thinly slice the onion.", "Heat olive oil in a 8-10 inch non-stick pan over medium heat. Add potatoes and onions, season with salt and pepper.", "Cook slowly, stirring occasionally, until potatoes are tender and onions are translucent, about 20-25 minutes. Do not brown.", "Drain excess oil from potatoes and onions, reserving about 1 tablespoon in the pan. Let potatoes cool slightly.", "In a large bowl, whisk eggs with a pinch of salt and pepper. Fold in the potato and onion mixture.", "Pour the egg mixture back into the same pan over medium-low heat. Cook for 8-10 minutes, until edges are set and bottom is golden.", "Place a large plate over the pan, carefully invert the tortilla onto the plate, then slide it back into the pan to cook the other side for 5-7 minutes.", "Cook until set through. Slide onto a clean plate, slice into wedges, and serve warm or at room temperature."]'::jsonb, 45, 2, 'seed/r24.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: potatoes, eggs, onion, olive oil
Dietary preference: Vegetarian', null, '2026-10-19T09:41:30-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'apples, oats, butter, brown sugar, cinnamon', 'vegetarian', 'Quick Apple Crumble', 'A warm and comforting dessert featuring tender baked apples with a buttery, cinnamon-spiced oat topping.', '[{"item": "apples", "amount": "2 medium"}, {"item": "rolled oats", "amount": "1/2 cup"}, {"item": "unsalted butter", "amount": "1/4 cup"}, {"item": "brown sugar", "amount": "1/4 cup"}, {"item": "cinnamon", "amount": "1/2 tsp"}, {"item": "all-purpose flour", "amount": "2 tbsp"}]'::jsonb, '["Preheat oven to 375\u00b0F (190\u00b0C). Grease two small ramekins or an 8x8 inch baking dish.", "Peel, core, and dice the apples into 1/2-inch pieces. Place them in the prepared baking dish(es).", "In a medium bowl, combine oats, brown sugar, cinnamon, and flour.", "Cut the cold butter into small pieces and add to the oat mixture. Use your fingers to rub the butter into the dry ingredients until crumbly.", "Sprinkle the oat crumble evenly over the apples.", "Bake for 30-35 minutes, or until apples are tender and the topping is golden brown and crispy.", "Let cool slightly before serving. Enjoy warm!"]'::jsonb, 40, 2, 'seed/r25.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: apples, oats, butter, brown sugar, cinnamon
Dietary preference: Vegetarian', null, '2026-10-10T19:08:39-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('bd9c66b3-ad3c-4d6d-9a3d-1fa7bc8960a9', 'corn tortillas, chicken, lime, jalapeno, onion', 'any', 'Spicy Chicken Tacos with Pickled Onions', 'Flavorful chicken tacos with a kick of jalapeno and bright, quick-pickled onions, all nestled in warm corn tortillas.', '[{"item": "chicken breast or thighs", "amount": "1 lb"}, {"item": "corn tortillas", "amount": "8-12"}, {"item": "lime", "amount": "1"}, {"item": "jalapeno", "amount": "1"}, {"item": "red onion", "amount": "1/2"}, {"item": "garlic powder", "amount": "1 tsp"}, {"item": "cumin", "amount": "1/2 tsp"}]'::jsonb, '["Thinly slice the red onion and place in a small bowl. Squeeze half the lime over the onions, add a pinch of salt, and set aside to quick-pickle.", "Dice the chicken into small, bite-sized pieces. Mince the jalapeno (remove seeds for less heat).", "Heat a tablespoon of oil in a skillet over medium-high heat. Add chicken and cook until browned.", "Stir in minced jalapeno, garlic powder, and cumin. Cook for another 3-5 minutes until chicken is cooked through.", "Warm the corn tortillas according to package directions or in a dry skillet for 30 seconds per side.", "Assemble tacos by filling warm tortillas with the cooked chicken. Top with the quick-pickled red onions and a squeeze of the remaining lime.", "Serve immediately."]'::jsonb, 35, 2, 'seed/r26.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: corn tortillas, chicken, lime, jalapeno, onion
Dietary preference: No restrictions', null, '2026-10-10T22:58:53-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('e2acf72f-9e57-4f7a-a0ee-89aed453dd32', 'eggplant, tomato sauce, mozzarella, breadcrumbs', 'vegetarian', 'Quick Eggplant Parmesan', 'A delicious and easy vegetarian take on classic eggplant parmesan, perfect for a satisfying meal.', '[{"item": "Eggplant", "amount": "1 large"}, {"item": "Tomato sauce", "amount": "1 cup"}, {"item": "Mozzarella cheese", "amount": "1 cup shredded"}, {"item": "Breadcrumbs", "amount": "1/2 cup"}, {"item": "Olive oil", "amount": "2 tbsp"}, {"item": "Garlic powder", "amount": "1/2 tsp"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C). Slice eggplant into 1/2-inch thick rounds.", "Toss eggplant slices with olive oil, salt, pepper, and garlic powder. Lightly coat both sides of each slice with breadcrumbs.", "Arrange eggplant on a baking sheet and bake for 15 minutes, flipping halfway, until tender and lightly golden.", "Spread a thin layer of tomato sauce in an oven-safe dish. Layer half the eggplant slices over the sauce.", "Top eggplant with half the remaining tomato sauce and half the mozzarella cheese.", "Repeat with the remaining eggplant, tomato sauce, and mozzarella.", "Bake for 15-20 minutes, or until the cheese is melted and bubbly.", "Let stand for a few minutes before serving."]'::jsonb, 40, 2, 'seed/r27.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: eggplant, tomato sauce, mozzarella, breadcrumbs
Dietary preference: Vegetarian', null, '2026-10-08T20:08:52-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'cottage cheese, eggs, spinach, turkey', 'high-protein', 'High-Protein Turkey and Spinach Scramble with Cottage Cheese', 'A quick and satisfying high-protein scramble, packed with savory turkey, fresh spinach, and creamy cottage cheese for a nutritious start to your day.', '[{"item": "Large eggs", "amount": "2"}, {"item": "Cottage cheese", "amount": "1/2 cup"}, {"item": "Cooked turkey (diced or shredded)", "amount": "3 oz"}, {"item": "Fresh spinach", "amount": "1 cup"}, {"item": "Olive oil", "amount": "1 tsp"}, {"item": "Salt", "amount": "Pinch"}, {"item": "Black pepper", "amount": "Pinch"}]'::jsonb, '["Heat olive oil in a non-stick pan over medium heat.", "Add diced turkey and cook for 2-3 minutes until lightly browned.", "Stir in the fresh spinach and cook until wilted, about 1-2 minutes.", "In a bowl, whisk eggs with salt and pepper.", "Pour the egg mixture into the pan and scramble with the turkey and spinach.", "Once eggs are nearly set, gently fold in the cottage cheese.", "Cook for another minute until cottage cheese is warmed through.", "Serve immediately and enjoy your protein-packed meal!"]'::jsonb, 15, 1, 'seed/r28.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: cottage cheese, eggs, spinach, turkey
Dietary preference: High protein', null, '2026-10-14T20:28:35-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('0e51f30d-c6a7-4e39-84b0-32ccd7c524a5', 'peanut noodles, cucumber, peanut butter, sriracha', 'vegan', 'Spicy Peanut Noodles with Cucumber', 'A quick, satisfying, and spicy vegan noodle dish featuring crunchy cucumber and a rich peanut sriracha sauce.', '[{"item": "peanut noodles", "amount": "2 servings"}, {"item": "cucumber", "amount": "1 large"}, {"item": "peanut butter", "amount": "1/4 cup"}, {"item": "sriracha", "amount": "1-2 tbsp (to taste)"}, {"item": "soy sauce", "amount": "2 tbsp"}, {"item": "lime juice", "amount": "1 tbsp"}]'::jsonb, '["Cook peanut noodles according to package directions, then drain and set aside.", "While noodles cook, thinly slice the cucumber into half-moons or ribbons.", "In a medium bowl, whisk together peanut butter, sriracha, soy sauce, and lime juice until smooth.", "If the sauce is too thick, add a tablespoon of hot water from the noodle pot to thin it.", "Add the cooked noodles to the sauce and toss until evenly coated.", "Stir in most of the sliced cucumber, reserving some for garnish.", "Divide between two bowls and top with the remaining fresh cucumber."]'::jsonb, 20, 2, 'seed/r29.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: peanut noodles, cucumber, peanut butter, sriracha
Dietary preference: Vegan', null, '2026-10-20T15:00:00-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('bdd640fb-0667-4ad1-9c80-317fa3b1799d', 'leftover pizza, eggs, arugula', 'dorm-friendly', 'Pizza & Egg Arugula Scramble', 'Turn that leftover pizza into a savory, satisfying scramble with eggs and fresh arugula.', '[{"item": "leftover pizza", "amount": "1-2 slices"}, {"item": "eggs", "amount": "2"}, {"item": "arugula", "amount": "1 cup"}, {"item": "olive oil", "amount": "1 tsp"}]'::jsonb, '["Cut the leftover pizza into small, bite-sized pieces.", "Heat olive oil in a non-stick pan over medium heat.", "Add pizza pieces to the pan and cook for 3-5 minutes, stirring occasionally, until slightly crispy.", "While pizza cooks, whisk eggs with a pinch of salt and pepper.", "Pour whisked eggs over the pizza in the pan and scramble until cooked through.", "Stir in the arugula until just wilted, about 1 minute.", "Serve immediately and enjoy your upgraded leftovers!"]'::jsonb, 15, 1, 'seed/r30.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: leftover pizza, eggs, arugula
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-10-13T12:17:30-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ff50bde4-3825-47b8-9cab-cc97663f1c97', 'steak, potatoes, garlic, rosemary', 'high-protein', 'Rosemary Garlic Steak & Potatoes', 'A classic and satisfying meal featuring perfectly seared steak and roasted potatoes infused with aromatic rosemary and garlic.', '[{"item": "Steak (e.g., sirloin, ribeye)", "amount": "1 lb"}, {"item": "Potatoes (e.g., russet, yukon gold)", "amount": "1 lb"}, {"item": "Garlic cloves", "amount": "4"}, {"item": "Fresh rosemary", "amount": "2 sprigs"}, {"item": "Olive oil", "amount": "2 tbsp"}, {"item": "Butter", "amount": "1 tbsp"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C). Wash and cut potatoes into 1-inch cubes.", "Toss potatoes with 1 tbsp olive oil, minced garlic from 2 cloves, salt, and pepper on a baking sheet. Roast for 25-30 minutes, flipping halfway.", "Pat steak dry and season generously with salt and pepper. Chop remaining garlic and rosemary.", "Heat 1 tbsp olive oil in a cast-iron or heavy-bottomed skillet over high heat until shimmering.", "Sear steak for 3-4 minutes per side for medium-rare, or until desired doneness. Reduce heat to medium.", "Add butter, remaining chopped garlic, and rosemary to the skillet. Baste steak with the melted butter mixture for 1 minute.", "Remove steak from skillet and let rest on a cutting board for 5-10 minutes before slicing.", "Serve sliced steak immediately with the roasted rosemary garlic potatoes."]'::jsonb, 45, 2, 'seed/r31.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: steak, potatoes, garlic, rosemary
Dietary preference: High protein', null, '2026-10-20T08:52:38-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('29a3b2e9-5d65-4441-9588-42dea2bc372f', 'miso, tofu, seaweed, scallions, rice', 'vegan', 'Quick Miso Tofu Rice Bowl', 'A comforting and savory vegan bowl featuring crispy tofu, umami miso, and fresh scallions over fluffy rice, perfect for a quick and satisfying meal.', '[{"item": "Firm Tofu", "amount": "1 block (14 oz)"}, {"item": "Miso Paste", "amount": "2 tbsp"}, {"item": "Dried Seaweed (wakame or nori)", "amount": "1/4 cup"}, {"item": "Scallions", "amount": "2 stalks"}, {"item": "White Rice", "amount": "1 cup (dry)"}, {"item": "Soy Sauce", "amount": "1 tbsp"}, {"item": "Sesame Oil", "amount": "1 tsp"}]'::jsonb, '["Cook rice according to package directions; set aside.", "Press tofu to remove excess water, then cut into 1-inch cubes.", "Heat a pan with oil over medium-high heat. Add tofu and cook until golden brown and crispy on all sides.", "While tofu cooks, whisk miso paste with 1/2 cup warm water until smooth to create a sauce.", "Add the rehydrated seaweed and soy sauce to the pan with the tofu, stir gently for 1 minute.", "Pour the miso sauce over the tofu and seaweed, simmering for 2-3 minutes until slightly thickened.", "Slice scallions thinly for garnish.", "Divide rice into bowls, top with miso tofu mixture, drizzle with sesame oil, and sprinkle with fresh scallions."]'::jsonb, 30, 2, 'seed/r32.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: miso, tofu, seaweed, scallions, rice
Dietary preference: Vegan', null, '2026-10-20T11:23:02-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('98ae4334-6c12-4ce8-ae34-0454cac5b68c', 'zucchini, ricotta, lemon, pasta', 'vegetarian', 'Creamy Lemon Ricotta Zucchini Pasta', 'A light and bright pasta dish featuring fresh zucchini and a creamy lemon-ricotta sauce, perfect for a quick weeknight meal.', '[{"item": "zucchini", "amount": "2 medium"}, {"item": "ricotta cheese", "amount": "1/2 cup"}, {"item": "lemon", "amount": "1"}, {"item": "pasta", "amount": "200g"}, {"item": "garlic", "amount": "2 cloves"}, {"item": "Parmesan cheese", "amount": "1/4 cup"}]'::jsonb, '["Bring a pot of salted water to a boil and cook pasta according to package directions.", "While pasta cooks, grate the zucchini and finely mince the garlic.", "In a large pan, heat a drizzle of olive oil over medium heat and saut\u00e9 garlic for 1 minute.", "Add grated zucchini to the pan and cook until softened, about 5-7 minutes; season with salt and pepper.", "In a bowl, combine ricotta cheese, the zest and juice of half a lemon, and half of the Parmesan cheese.", "Drain the pasta, reserving about 1/2 cup of pasta water.", "Add the cooked pasta and ricotta mixture to the pan with the zucchini, tossing to combine.", "If needed, add a splash of reserved pasta water to create a creamy sauce; serve immediately with remaining Parmesan."]'::jsonb, 25, 2, 'seed/r33.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: zucchini, ricotta, lemon, pasta
Dietary preference: Vegetarian', null, '2026-10-07T22:44:27-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('bd9c66b3-ad3c-4d6d-9a3d-1fa7bc8960a9', 'hot dogs, baked beans, cheddar, bread', 'any', 'Cheesy Hot Dog & Bean Melts', 'A quick and satisfying open-faced sandwich, featuring classic hot dogs and baked beans made irresistible with a blanket of melted cheddar.', '[{"item": "Hot dogs", "amount": "4"}, {"item": "Baked beans", "amount": "1 can (15 oz)"}, {"item": "Cheddar cheese, shredded", "amount": "1 cup"}, {"item": "Bread slices", "amount": "4"}, {"item": "Butter or mayonnaise", "amount": "for spreading (optional)"}]'::jsonb, '["Preheat your oven''s broiler to high and line a baking sheet with foil.", "Slice hot dogs into coins or lengthwise halves. In a small saucepan, heat the hot dog pieces and baked beans over medium heat until warm.", "Lightly toast the bread slices, either in a toaster or pan, until golden.", "Spread a thin layer of butter or mayonnaise on one side of each toast slice, if desired.", "Top each toast slice generously with the hot dog and bean mixture.", "Sprinkle a good amount of shredded cheddar cheese over the bean mixture on each toast.", "Place the topped toasts on the prepared baking sheet and broil for 2-4 minutes, or until the cheese is bubbly and golden brown.", "Carefully remove from the oven and serve immediately."]'::jsonb, 20, 2, 'seed/r34.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: hot dogs, baked beans, cheddar, bread
Dietary preference: No restrictions', null, '2026-10-07T09:35:08-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('ddd1dfb2-3b98-4ef8-9af6-1a26146d3f31', 'chocolate chips, flour, butter, eggs, sugar', 'vegetarian', 'Classic Chocolate Chip Cookies', 'Chewy on the inside, crispy on the outside, these classic chocolate chip cookies are a timeless treat.', '[{"item": "All-purpose flour", "amount": "1 1/4 cups"}, {"item": "Unsalted butter, softened", "amount": "1/2 cup"}, {"item": "Granulated sugar", "amount": "1/2 cup"}, {"item": "Packed light brown sugar", "amount": "1/4 cup"}, {"item": "Large egg", "amount": "1"}, {"item": "Vanilla extract", "amount": "1 teaspoon"}, {"item": "Baking soda", "amount": "1/2 teaspoon"}, {"item": "Salt", "amount": "1/4 teaspoon"}, {"item": "Semi-sweet chocolate chips", "amount": "1 cup"}]'::jsonb, '["Preheat oven to 375\u00b0F (190\u00b0C). Line a baking sheet with parchment paper.", "In a small bowl, whisk together flour, baking soda, and salt.", "In a large bowl, cream together softened butter, granulated sugar, and brown sugar until light and fluffy.", "Beat in the egg and vanilla extract until well combined.", "Gradually add the dry ingredients to the wet ingredients, mixing until just combined.", "Stir in the chocolate chips until evenly distributed.", "Drop rounded tablespoons of dough onto the prepared baking sheet, about 2 inches apart.", "Bake for 9-11 minutes, or until the edges are golden brown and the centers are still soft. Let cool on the baking sheet for a few minutes before transferring to a wire rack."]'::jsonb, 35, 12, 'seed/r35.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: chocolate chips, flour, butter, eggs, sugar
Dietary preference: Vegetarian', null, '2026-10-19T07:33:01-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('0e51f30d-c6a7-4e39-84b0-32ccd7c524a5', 'bananas, frozen berries, spinach, almond milk', 'vegan', 'Berry Banana Green Smoothie Bowl', 'A vibrant and refreshing smoothie bowl packed with fruits and greens, perfect for a quick and healthy meal.', '[{"item": "Bananas", "amount": "1 large, frozen (sliced before freezing "}, {"item": "Frozen mixed berries", "amount": "1 cup"}, {"item": "Fresh spinach", "amount": "1 cup packed"}, {"item": "Unsweetened almond milk", "amount": "1/2 cup (or more for desired consistency"}, {"item": "Chia seeds", "amount": "1 tablespoon (optional, for topping)"}, {"item": "Granola", "amount": "1/4 cup (optional, for topping)"}]'::jsonb, '["Combine frozen banana, frozen berries, spinach, and almond milk in a blender.", "Blend on high until completely smooth and creamy, adding more almond milk if needed for desired consistency.", "Pour the smoothie into a bowl.", "Top with chia seeds and granola if using.", "Serve immediately and enjoy."]'::jsonb, 10, 1, 'seed/r36.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: bananas, frozen berries, spinach, almond milk
Dietary preference: Vegan', null, '2026-10-18T19:32:36-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('366eb16f-508e-4ad7-b7c9-3acfe059a0ee', 'rotisserie chicken, tortilla wraps, lettuce, ranch', 'dorm-friendly', 'Crispy Chicken Ranch Wraps', 'Quick and satisfying wraps filled with warm, crispy chicken, cool lettuce, and creamy ranch, perfect for a dorm room feast.', '[{"item": "Rotisserie chicken", "amount": "2 cups shredded"}, {"item": "Large tortilla wraps", "amount": "2"}, {"item": "Lettuce", "amount": "1 cup shredded"}, {"item": "Ranch dressing", "amount": "4 tbsp"}, {"item": "Garlic powder", "amount": "1/2 tsp"}]'::jsonb, '["Shred the rotisserie chicken into bite-sized pieces and place in a microwave-safe bowl.", "Sprinkle the chicken with garlic powder, salt, and pepper, then microwave for 1-2 minutes until heated through.", "Lay out a tortilla wrap and spread 2 tablespoons of ranch dressing over it.", "Arrange half of the warm chicken and half of the shredded lettuce down the center of the tortilla.", "Fold in the sides of the tortilla, then tightly roll it up from the bottom.", "Repeat with the second tortilla and serve immediately."]'::jsonb, 15, 2, 'seed/r37.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: rotisserie chicken, tortilla wraps, lettuce, ranch
Dietary preference: Dorm friendly (microwave / one pan)', null, '2026-09-30T19:45:58-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('0e51f30d-c6a7-4e39-84b0-32ccd7c524a5', 'cod, potatoes, peas, flour, lemon', 'any', 'Lemon Herb Pan-Seared Cod with Roasted Potatoes and Peas', 'Flaky cod with a zesty lemon crust, served alongside tender roasted potatoes and sweet peas for a complete and satisfying meal.', '[{"item": "Cod fillets", "amount": "2 (about 6 oz each)"}, {"item": "Potatoes", "amount": "2 large"}, {"item": "Peas", "amount": "1 cup (frozen)"}, {"item": "All-purpose flour", "amount": "1/4 cup"}, {"item": "Lemon", "amount": "1"}, {"item": "Olive oil", "amount": "2 tbsp"}, {"item": "Dried dill", "amount": "1 tsp"}, {"item": "Garlic powder", "amount": "1/2 tsp"}]'::jsonb, '["Preheat oven to 400\u00b0F (200\u00b0C). Dice potatoes into 1-inch cubes, toss with 1 tbsp olive oil, salt, and pepper, then spread on a baking sheet.", "Roast potatoes for 25-30 minutes, flipping halfway, until golden and tender.", "While potatoes roast, pat cod fillets dry. In a shallow dish, mix flour, garlic powder, dill, salt, and pepper.", "Dredge each cod fillet in the flour mixture, shaking off excess.", "Heat 1 tbsp olive oil in a large non-stick pan over medium-high heat. Sear cod for 3-5 minutes per side, until golden brown and cooked through.", "In the last 5 minutes of potato roasting, add peas to the baking sheet or microwave them separately.", "Squeeze fresh lemon juice over the cooked cod.", "Serve the pan-seared cod with roasted potatoes and peas."]'::jsonb, 45, 2, 'seed/r38.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: cod, potatoes, peas, flour, lemon
Dietary preference: No restrictions', null, '2026-10-07T23:35:36-04:00');
insert into public.recipes (user_id, pantry, diet, title, description, ingredients, steps, minutes, servings, image_path, model, image_model, system_prompt, user_prompt, raw_response, created_at)
values ('24933b83-7577-40a9-a491-f0b2ea1fca65', 'cabbage, bacon, onion, apple cider vinegar', 'any', 'Sweet and Sour Cabbage with Bacon', 'A delightful balance of smoky, tangy, and slightly sweet flavors, turning simple ingredients into a comforting meal.', '[{"item": "Bacon", "amount": "4 strips"}, {"item": "Yellow onion", "amount": "1/2 medium"}, {"item": "Green cabbage", "amount": "1/2 head"}, {"item": "Apple cider vinegar", "amount": "2 tbsp"}, {"item": "Brown sugar", "amount": "1 tbsp"}, {"item": "Water", "amount": "1/4 cup"}]'::jsonb, '["Chop bacon into 1/2 inch pieces and cook in a large skillet over medium heat until crispy. Remove bacon with a slotted spoon, leaving rendered fat in the pan.", "Thinly slice the onion and cabbage. Add onion to the skillet and cook in bacon fat until softened, about 5 minutes.", "Add the sliced cabbage to the skillet and cook, stirring occasionally, until it begins to wilt and soften, about 10-15 minutes.", "In a small bowl, whisk together apple cider vinegar, brown sugar, and water.", "Pour the vinegar mixture over the cabbage and stir well. Bring to a simmer and cook for another 5-7 minutes, until cabbage is tender-crisp.", "Stir in the cooked bacon. Taste and adjust seasoning with salt and pepper if needed. Serve hot."]'::jsonb, 35, 2, 'seed/r39.jpg', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-image', (select system_prompt from public.recipes where system_prompt like 'You are a home cook%' limit 1), 'Ingredients I have: cabbage, bacon, onion, apple cider vinegar
Dietary preference: No restrictions', null, '2026-10-15T20:54:24-04:00');
